// ----------------------------------------------------------------------------------------- //
// Data Object Declaration & Definition
// ----------------------------------------------------------------------------------------- //
// =======================================
// 1. THE "TECH UNIT" GENERATOR
// =======================================
// This ensures every technology has the exact same structure.
const Tech = ({ icon, label, accent, hover, tag = null }) => ({
  icon,         // JSX SVG
  label,        // String name
  accent,       // Tailwind text color class (e.g., "text-yellow-400")
  hover,        // Tailwind border color class (e.g., "hover:border-yellow-500/50")
  tag           // Optional Object: { label, bg, text }
});

// Helper: Common Tags
const TAG_EXPLORING = {label: "Exploring", bg: "bg-emerald-600/30", text: "text-emerald-300"}
const TAG_NEW = { label: "New", bg: "bg-lime-500/30", text: "text-lime-300" };
const TAG_CORE = { label: "Core", bg: "bg-amber-600/30", text: "text-amber-300" };
const TAG_EXPERT = { label: "Expert", bg: "bg-fuchsia-500/30", text: "text-fuchsia-300" };

const addTag = (tech, value) => ({
  ...tech,
  tag: value
});

// =======================================
// 2. ICONS (Responsive w-full h-full)
// =======================================
